// Adds DWARF source file line number info to the current binary as EOL comments.
// Note that you can run this script on a program that has already been analyzed by the
// DWARF analyzer.
//@category DWARF



using ghidra.app.script;
using ghidra.app.util.bin.format.dwarf;
using ghidra.app.util.bin.format.dwarf.line.DWARFLine;
using ghidra.app.util.bin.format.dwarf.sectionprovider;
using ghidra.app.util.bin.format.dwarf.sectionprovider;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util.exception;

public class DWARFLineInfoCommentScript : GhidraScript {
	/* @Override */
	protected void run()
    {
		DWARFSectionProvider dsp =
			DWARFSectionProviderFactory.createSectionProviderFor(currentProgram, monitor);
		if (dsp == null) {
			printerr("Unable to find DWARF information");
			return;
		}

		DWARFImportOptions importOptions = new DWARFImportOptions();
		using (DWARFProgram dprog = new DWARFProgram(currentProgram, importOptions, dsp))
{
			dprog.init(monitor);
			addSourceLineInfo(dprog);
		}
	}

	private void addSourceLineInfo(DWARFProgram dprog)
    {
		if (!dprog.getDIEContainer().hasLineInfo()) {
			return;
		}
		int count = 0;
		monitor.initialize(dprog.getDIEContainer().getLineDataSize(), "DWARF Source Line Info");
		foreach (DWARFCompilationUnit cu in dprog.getDIEContainer().getCompilationUnits()) {
			try {
				monitor.checkCancelled();
				monitor.setProgress(cu.getLine().getStartOffset());
				List<SourceFileAddr> allSFA = cu.getLine().getAllSourceFileAddrInfo(cu);
				foreach (SourceFileAddr sfa in allSFA) {
					Address addr = dprog.getCodeAddress(sfa.address());
					DWARFUtil.appendComment(currentProgram, addr, CommentType.EOL, "",
						"%s:%d".formatted(sfa.fileName(), sfa.lineNum()), ";");
					count++;
				}
			}
			catch (IOException e) {
				Msg.error(this,
					"Failed to read DWARF line info for cu %d".formatted(cu.getUnitNumber()), e);
			}
		}
		println("Marked up " + count + " locations with source info");
	}
}
